"""Publish already verified settlement-premium cash-defense BTC accounts; never rerun research."""
import csv,json,zipfile
from pathlib import Path
from build_btc_web_report import read,table
from btc_perp_bot.research.archive import canonical,sha
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-peg-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fc=read(RUN/'forecast-summary.json')
 assert len(s)==v['accounts']==60 and rep['all_bytes_equal'] and rep['matched_files']==103 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[]
 for n in ('PG_INFO','PG_PRICE','PG_SHORT','PG_INV','PG_TREND'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='PG_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]])
   cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.4f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('PG_PRICE','PG_TREND'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')},'usd_translation_return_pct':e['usd_translation']['return_pct']})
 for p,lags in fc.items():
  for lag,models in lags.items():
   for n,x in models.items():forecast.append([p,lag,n,x['n'],f"{x['mse']:.9f}",f"{x['sign_accuracy']*100:.2f}",x['constraint_days']])
 evidence={'build':'1003p1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development; continuous settlement premium with current API vintage; BTC/USD forecast vs USDT account; cash defense not USDT strategy; no accepted strategy'}
 (DOWN/'btc-peg-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-peg-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-peg-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_peg_study.py','test_btc_peg_study.py','verify_btc_peg_study.py','reproduce_btc_peg_study.py','btc_target_ledger.py'):files.append((ROOT/'tools'/n,'source/'+n))
  for n in ('independent-audit.json','data-audit.json','archive-manifest.json','masks.json'):files.append((ROOT/'data/btc-venue-20261003'/n,'input/'+n))
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,3,0,0,0)),'All 60 accounts, USD labels, features, forecasts, masks, independent checks and source metadata included. Reproduction additionally requires the frozen Coinbase BTCUSD/USDTUSD hourly raw responses, normalized candles, prior native-daily audit, official Binance BTC spot/perp/mark/funding archives and common Python/package dependencies. The old candle file also contains unused Bitstamp BTCUSD rows. No original paper PDF or third-party research code is redistributed. Current API downloads need not recover this exact vintage. No USDT/other-asset strategy, addresses, individual transactions or live orders. USD return translation is not a currency conversion execution.\n')
 html="""<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self';script-src 'none';style-src 'self';img-src 'self' data:;connect-src 'none';object-src 'none';base-uri 'none';form-action 'none'"><title>BTC 결제 프리미엄 방어 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1003p1</p><h1>결제통화의 프리미엄,<br>BTC 방어 성과는 늘리지 못했습니다.</h1><p class="lead">양의 USDT/USD 프리미엄이 다음 날 BTC 달러 하락 정보를 주는지 검사했습니다. 기본은 현물 노출을 현금으로 줄이는 규칙이지만, 주기간에는 기존 추세보다 낮았고 최근에는 방어 사건이 없었습니다.</p><div class="facts"><article><b>60</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>PG_INFO 기본 후보</span></article><article><b>103</b><span>파일 차단 재현 일치</span></article></div><p class="boundary">이미 본 2022–2025 / 2026.01–08 개발 자료이며 미사용 OOS·실전 성과가 아닙니다. BTC만 거래하는 가상검증입니다. USDT/USD는 정보 입력이지 USDT 매매·송금·발행 전략이 아닙니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT, 수익·최대낙폭(DD)은 %. 현금도 USDT 단위이며 달러와 동일시하지 않습니다.</p>"""+table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results')+"""<p>기본 주 +52.33%·DD13.75%, 최근 +0.89%·DD1.68%. 주수익&gt;52.838713%·DD≤13.561952%, 최근수익&gt;4.628391% 기준을 유지했습니다. 2022 −4.21%, 2025 −2.06%로 연도 일관성도 미달입니다. 가격 대조의 주 +53.56%나 반대 대조의 +53.47%를 새 기본으로 바꾸지 않았습니다.</p></section><section><h2>통화 효과와 BTC 예측을 분리했습니다</h2><p>완료한 USDT/USD 24시간 종가의 평균 로그 프리미엄을 사용했습니다. 이미 발생한 BTC/USD 1일·7일 수익과 USDT/USD 1일 변화를 통제하고, 다음 날 <strong>BTC/USD</strong> 수익에 프리미엄의 음의 추가정보가 있는지 과거365달력일·최소126행으로 추정했습니다. 원문의 점프 검정을 시간봉에 그대로 옮기지 않았습니다.</p><p>양의 프리미엄, 비용23bp+한SE보다 큰 하락 예측, 가격 대조보다 음의 추가정보가 동시에 있을 때만 기본은 현금0 목표입니다. 최근완료봉+1h 대기, 추가24h 조건에서는 학습 label의 가용성도 늦췄습니다. 목표0을 신호없음과 혼동하지 않았습니다.</p><p>INFO의 방어 사건은 주14일·최근0일입니다. PRICE는 가격만으로 현금 방어, SHORT는 INFO와 같은 날 BTC 선물 숏, INV는 같은 날 BTC 현물 롱, TREND는 기존 가격 추세입니다. 최근 기본과 세 방향 대조의 성과가 같다는 것은 독립 성공이 아니라 신호 부재입니다.</p><p>예측은 USD, 거래원장은 native USDT이므로 거래소 basis·환율 위험이 남습니다. 시작/끝 실제 입력 환율로 단순 환산한 기본 USD 총수익은 주 +52.10%·최근 +1.00%이며 환전 체결·USD 현금 수익을 보장하지 않습니다. 전체60계좌 환산값은 JSON/CSV에 보존했습니다.</p></section><section><h2>근거를 좁혀 읽었습니다</h2><p>NBER 원문은 결제 편의·불안 수요의 프리미엄을 설명하지만 발행량의 BTC 가격 효과는 찾지 못했습니다. USDT 점프 원문은 전체표본·당기식·표본 수/단위/시간 표기의 한계가 있으며 거래비용을 반영한 전략 검증은 없습니다. 원 점프검정의 저빈도 과대기각도 확인했습니다. 이 실험은 원문 복제가 아닌 자체 경제 질문입니다.</p><p>기존 공식 Coinbase BTCUSD·USDTUSD 동결자료만 재사용했습니다. 390응답·93,451시간행을 Decimal로 다시 읽고, 기존12개 목적표본 일봉 감사는 영수증을 재사용했습니다. BTCUSD13시간·FX88시간 누락, 초기 빈 일봉·0량 마스크는 채우지 않았습니다. 현재 과거 API는 당시 첫 공표 빈티지를 증명하지 못합니다.</p></section><section><h2>예측과 내구성</h2><p>공통표본 주1,459일의 USD 목표 MSE는 INFO 0.000754383 vs PRICE 0.000747815로 악화했습니다. 최근242일은 0.000618091 vs 0.000618434로 조금 낮지만 기본 방어는0일이고 양기간 추가정보 관문은 미충족입니다. 양의 프리미엄 계수라 제약이 활성된 날은 주1,133일·최근212일이었습니다.</p><p>기본 비용2배 주 +46.36%·최근 +0.65%, 실행24h지연 주 +35.10%·최근 −1.35%. 자료24h지연 주 +52.84%는 기존 추세와 같은 결과일 뿐 기본을 대신하지 않습니다. 최근 신호 부재에서도 실행 지연은 공통 추세 거래를 바꾸므로 지연 손실을 숨기지 않습니다.</p><details><summary>모든 USD 예측과 추가24시간 자료지연</summary>"""+table(['기간','추가지연(시간)','모형','공통표본','MSE','방향정확도%','제약활성일'],forecast,'forecast-results')+'</details><details><summary>연도별 수익</summary>'+table(['규칙','기간','2022','2023','2024','2025','2026'],annual,'annual-results')+'</details><details><summary>롱숏·비용·펀딩·위험</summary>'+table(['규칙','기간','가격손익','비용','펀딩','평균노출%','연변동성%','롱 순손익','숏 순손익'],cost,'cost-results')+'</details><details><summary>대조군 차이의 불확실성</summary><p>14일 블록2,000회95%구간(%/일), 7/28일 JSON 포함. 반복 개발·단일 거래소·현재 빈티지 편향을 제거하지 못합니다.</p>'+table(['규칙','기간','대조','일수익차95%구간'],ci,'uncertainty-results')+'</details></section><section><h2>비용·지연·위험 조건을 모두 보존했습니다</h2><p>현물10bp/선물5bp 수수료+각1.5bp 불리 impact, 실제 funding, 최소수량·최소금액·5%p 밴드·종료비용, 명목상한1배·20%위험목표. 비용2배·실행1/24h·위험10%·자료24h 모든 조건입니다. 실제호가/부분체결/모든과거규정/정확청산/세금·운영비는 미복원입니다.</p><details id="matrix"><summary>60계좌 전체 보기</summary>'+table(['규칙','기간','조건','수익%','DD%','연변동성%','보유구간','비용'],[[r['strategy'],r['period'],r['scenario'],f"{r['return_pct']:+.2f}",f"{r['max_drawdown_pct']:.2f}",f"{r['realized_vol_pct']:.2f}",r['round_trips'],f"{r['fees']+r['impact']:.2f}"] for r in rows],'all-accounts')+'</details></section>'
 html+="""<section id="proof"><h2>독립 검산과 소켓차단 재현</h2><p>성과 전15개 검사, 7,240개 독립 정규방정식/HAC, 3,898피처일, 25,560일간 판단, 7,127폐형식 수량·43,994무거래, 246펀딩·7,403이벤트·51,120일말 자산과 90블록 신뢰구간을 검산했습니다. 시간DD/담보/연도·선정·60USD환산도 별도 대조했습니다. 최대계좌차2×10⁻¹¹USDT, 모형수치차6×10⁻¹¹ 이하.</p><p>103파일 소켓차단 바이트 동일. 사전12f17ff → 구현001415f 뒤 계산했습니다. 검산 성공은 전략 성공이 아닙니다. 기존198계좌/273파일과 앞선1,254조건계좌는 변경·재실행하지 않았습니다.</p></section><section id="downloads"><h2>검증 자료</h2><div class="downloads"><a download href="downloads/btc-peg-evidence.zip">60계좌·USD목표·피처·검산 ZIP ↓</a><a download href="downloads/btc-peg-evidence.json">전체 수치·불확실성 JSON ↓</a><a download href="downloads/btc-peg-summary.csv">60조건 CSV ↓</a></div><p><a href="EXPERIMENT_BTC_PEG_20261003.md">성과 전 명세</a> · <a href="BTC_WEB_RESEARCH_20261002.md">원문 감사·실패 기록</a> · <a href="https://www.nber.org/papers/w27136">결제 프리미엄 원문</a> · <a href="https://doi.org/10.1016/j.frl.2021.102644">점프 원문</a> · <a href="https://www.nuff.ox.ac.uk/economics/papers/2003/W21/split.pdf">검정 저자판</a></p><p>ZIP은 새 파생 결과·소스·입력 영수증이며 독립 실행 환경 전체가 아닙니다. 동결 원응답/정규화가격·공식 BTC ZIP·공통 의존성은 별도 필요합니다. 논문 PDF/외부 연구코드는 재배포하지 않았습니다. 현재 API 재다운로드가 같은 빈티지임을 보장하지 않습니다.</p><p>연구 목표는 미완료입니다. 실거래·실계좌 조회·상시모의 서비스는 없습니다.</p></section><footer>BUILD1003p1 · BTC-only · 실거래 없음</footer></main></body></html>"""
 (DOC/'btc-peg-research.html').write_text(html);p=DOC/'btc-web-research.html';old=p.read_text()
 if 'id="peg-followup"' not in old:p.write_text(old.replace('<h1>','<p id="peg-followup" class="boundary">추가60계좌: <a href="btc-peg-research.html">결제 프리미엄 현금 방어 검증 ↗</a></p><h1>',1))
 files=['btc-peg-research.html','btc-web-research.html','downloads/btc-peg-evidence.zip','downloads/btc-peg-evidence.json','downloads/btc-peg-summary.csv','EXPERIMENT_BTC_PEG_20261003.md','BTC_WEB_RESEARCH_20261002.md'];out=ROOT/'runs/btc-peg-report-20261003';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files),'zip_bytes':(DOWN/'btc-peg-evidence.zip').stat().st_size}))
